609	    /**
610	     * The single Luhn check digit (0-9) computed over the digits contained in {@code value}: non-digit
611	     * characters are ignored, each second digit from the right is doubled (subtracting 9 when the double
612	     * exceeds 9), the results are summed, and the check digit is {@code (10 - sum % 10) % 10}. This is
613	     * the CHK segment of the {@link #getMemberId() memberId}, computed over its {@code <REGION><FY><HASH8>}
614	     * prefix.
615	     */
616	    public static int luhnCheckDigit(String value) {
617	        int sum = 0;
618	        boolean dbl = true;
619	        for (int i = value.length() - 1; i >= 0; i--) {
620	            char c = value.charAt(i);
621	            if (c < '0' || c > '9') {
622	                continue;
623	            }
624	            int d = c - '0';
625	            if (dbl) {
626	                d *= 2;
627	                if (d > 9) {
628	                    d -= 9;
629	                }
630	            }
631	            sum += d;
632	            dbl = !dbl;
633	        }
634	        return (10 - (sum % 10)) % 10;
635	    }
